<script setup>
import {computed,ref,watch,onUnmounted} from 'vue';import AppDialog from './AppDialog.vue';import AppButton from './AppButton.vue';import AppInput from './AppInput.vue';import AppSelect from './AppSelect.vue';import AppSwitch from './AppSwitch.vue';import AppInfoBlock from './AppInfoBlock.vue';import AppDataCard from './AppDataCard.vue';import AppTable from './AppTable.vue';import ConfirmDialog from './ConfirmDialog.vue';import ConfigSelectionDialog from './ConfigSelectionDialog.vue';import {usePreferences} from '../preferences.js';import {notify} from '../lib/toasts.js';import {useProgressiveList} from '../lib/progressive.js';
const props=defineProps({open:Boolean,source:Object,api:Function});const emit=defineEmits(['close','saved']);const {t}=usePreferences();
const name=ref(''),url=ref(''),loadedUrl=ref(''),enabled=ref(true),intervalHours=ref('6'),busy=ref(false),picking=ref(false),records=ref([]),selected=ref([]),token=ref(''),recordsComplete=ref(true),confirmed=ref([]),pending=ref(null);let generation=0,controller;
const rows=computed(()=>records.value),{visible,onScroll}=useProgressiveList(rows);
watch(()=>props.open,async open=>{const cycle=++generation;controller?.abort();busy.value=false;picking.value=false;pending.value=null;confirmed.value=[];records.value=[];if(!open){url.value='';token.value='';return;}name.value=props.source?.name || '';url.value='';loadedUrl.value='';token.value='';enabled.value=props.source?.enabled!==false;intervalHours.value=String(props.source?.intervalHours || 6);if(props.source){busy.value=true;controller=new AbortController();try{const source=await props.api('gateway-subscriptions/'+props.source.id,{signal:controller.signal});if(cycle===generation){url.value=source.url;loadedUrl.value=source.url;records.value=source.records || [];recordsComplete.value=source.recordsComplete!==false;}}catch(error){if(cycle===generation && error.name!=='AbortError')notify(t(error.message),'error');}finally{if(cycle===generation)busy.value=false;}}});
onUnmounted(()=>{generation++;controller?.abort();url.value='';});
async function preview(){const cycle=generation;busy.value=true;controller=new AbortController();try{const result=await props.api('gateway-subscriptions/preview',{method:'POST',body:JSON.stringify({id:props.source?.id,name:name.value,url:url.value,enabled:enabled.value,intervalHours:Number(intervalHours.value)}),signal:controller.signal});if(cycle!==generation)return;recordsComplete.value=true;token.value=result.token;loadedUrl.value=url.value;records.value=result.records.map(row=>({...row,enabled:row.available!==false && row.enabled===true}));selected.value=result.selected;confirmed.value=[];if(!props.source)picking.value=true;}catch(error){if(cycle===generation && error.name!=='AbortError')notify(t(error.message),'error');}finally{if(cycle===generation)busy.value=false;}}
function toggle(row,value){if(!value && row.inUse && row.profileId && !confirmed.value.includes(row.profileId)){pending.value={rows:[row],retry:false};return;}row.enabled=value;if(value)confirmed.value=confirmed.value.filter(id=>id!==row.profileId);}
const confirmationMessage=computed(()=>{const list=pending.value?.rows || [],names=list.map(row=>row.label || row.name).join(', '),usage=[...new Set(list.flatMap(row=>Object.values(row.usage || {}).flat()))].join(', ');return t('Gateways {names} are used by: {usage}. Disabling them may interrupt these connections. Routing rules will be kept.',{names,usage});});
async function confirmDisable(){const request=pending.value;for(const row of request.rows){const current=records.value.find(item=>item.key===row.key);if(current)current.enabled=false;if(row.profileId && !confirmed.value.includes(row.profileId))confirmed.value.push(row.profileId);}pending.value=null;if(request.retry)await save();}
async function save(){if(props.source && url.value!==loadedUrl.value){await preview();return;}const cycle=generation;busy.value=true;try{const body=props.source?{name:name.value,url:url.value,enabled:enabled.value,intervalHours:Number(intervalHours.value),token:token.value || undefined,states:records.value.map(row=>({key:row.key,enabled:row.enabled===true})),confirmDisable:confirmed.value}:{token:token.value,selected:selected.value};await props.api('gateway-subscriptions'+(props.source?'/'+props.source.id+'/settings':''),{method:props.source?'PUT':'POST',body:JSON.stringify(body)});if(cycle===generation)emit('saved');}catch(error){if(cycle===generation){if(error.data?.code==='gateway-disable-confirmation-required')pending.value={rows:error.data.inUse,retry:true};else notify(t(error.message),'error');}}finally{if(cycle===generation)busy.value=false;}}
</script>
<template>
 <AppDialog :open="open && !picking" :wide="!!source" :form-session="open" :form-state="[name,url,enabled,intervalHours,records.map(row=>[row.key,row.enabled])]" :title="t(source?'Edit subscription':'Добавить подписку')" @close="emit('close')">
  <div class="form-section">
   <label>{{t('Название')}}<AppInput v-model="name" maxlength="100" :disabled="busy" data-testid="subscription-name" /></label>
   <label>{{t('Subscription URL')}}<AppInput v-model="url" type="url" autocomplete="off" :disabled="busy" data-testid="subscription-url" /></label>
   <AppSwitch v-model="enabled" :disabled="busy" :label="t('Automatic updates')" />
   <label v-if="enabled">{{t('Update interval')}}<AppSelect v-model="intervalHours" :disabled="busy" :label="t('Update interval')" :options="[1,6,12,24].map(value=>({value:String(value),label:t('Every {hours} hours',{hours:value})}))" /></label>
   <AppInfoBlock v-if="!source">{{t('Selected gateways are added disabled. Enable the gateways you need in the table.')}}</AppInfoBlock>
   <AppInfoBlock v-if="source && !recordsComplete">{{t('Update the subscription to load its full configuration list.')}}</AppInfoBlock>
   <AppDataCard v-if="source" :title="t('Subscription configurations')" :count="records.length">
    <template #actions><AppButton variant="secondary" size="s" :disabled="busy" @click="preview">{{t('Обновить')}}</AppButton></template>
    <div class="subscription-configs" @scroll="onScroll"><AppTable class="data-table" data-testid="subscription-config-list" :loading="busy"><thead><tr><th class="toggle-col" :aria-label="t('Включено')"></th><th>{{t('Название')}}</th><th>{{t('Тип')}}</th><th>{{t('Usage')}}</th></tr></thead><tbody><tr v-for="row in visible" :key="row.key" :data-key="row.key"><td @click.stop><AppSwitch :model-value="row.enabled" :disabled="busy || (!row.available && !row.enabled) || url!==loadedUrl" :label="t('Включено')" hide-label @update:model-value="toggle(row,$event)" /></td><td><strong>{{row.label}}</strong><div v-if="!row.available" class="muted">{{t('Not in current subscription')}}</div></td><td>{{row.type}}</td><td>{{row.inUse?Object.values(row.usage || {}).flat().join(', '):'—'}}</td></tr><tr v-if="!records.length && !busy" class="table-empty"><td colspan="4">{{t('Нет данных')}}</td></tr></tbody></AppTable></div>
   </AppDataCard>
  </div>
  <template #footer><AppButton variant="secondary" :disabled="busy" @click="emit('close')">{{t('Отмена')}}</AppButton><AppButton :disabled="busy || !name.trim() || !url.trim()" data-testid="subscription-load" @click="source?save():preview()">{{t(busy?'Загрузка…':source && url===loadedUrl?'Сохранить':'Load connections')}}</AppButton></template>
 </AppDialog>
 <ConfigSelectionDialog :open="open && picking" :records="records" v-model="selected" :disabled="busy" @close="picking=false" @confirm="save" />
 <ConfirmDialog :open="!!pending" :title="t('Disable gateways in use?')" :confirm-label="t('Отключить')" @close="pending=null" @confirm="confirmDisable"><AppInfoBlock variant="warning">{{confirmationMessage}}</AppInfoBlock></ConfirmDialog>
</template>
<style scoped>
.subscription-configs{max-height:50dvh;overflow:auto}
</style>
